// CSD_RATIONALE_BEGIN
// DIAGNOSIS:
// Best (attempt 18, 49.0%, 89.8%): used `next == "<<"` exact check and `break` after first span.
// Attempt 21 regression (30.6%, 77.6%): replaced with `RenderedEndsWith` everywhere + removed threshold.
//   - 11 unterminated spans: model writes "End with <<int(formula)>>" in mid-reasoning prose.
//     Space-prefixed token `" <<"` fires `RenderedEndsWith` but NOT `next == "<<"`. CSD enters
//     constrained mode prematurely; parser produces "int(form" then blocks non-alpha chars → span never closes.
//   - 9 tiny wrong spans (mode_F): model writes "<<n1>>" as intermediate calculation marker
//     (e.g., "... multiplied by c1 is <<n1>>"). Parser completes "n1", CSD breaks → wrong answer.
//
// TWO TARGETED FIXES:
//
// FIX 1 — naturalEntryThreshold = 150:
//   Before step 150, RenderedEndsWith detections from mid-reasoning "<<" are IGNORED.
//   The problematic space-prefixed `" <<"` tokens in phrases like "End with <<int(formula)"
//   appear typically in the first 50-120 steps of reasoning. After step 150, natural "<<"
//   detection activates; avg tokens-before-open = 237, so the real final "<<" is caught.
//   Force-open at prefixBudget=800 still handles late or absent natural "<<".
//
// FIX 2 — length-gated break (minSpanLength = 5):
//   After CloseSpanIfComplete returns closed=true, only break when preCloseLen >= 5.
//   Tiny spans like "<<n1>>" (constrained length 1) or "<<int(n)>>" (~3) → continue,
//   allowing the model to write the full formula in a subsequent span.
//   The evaluator uses the LAST visible span as the answer.
//   Substantial spans (5+ constrained tokens) → break as before.
//
// ALL OTHER PARAMETERS FROM BEST (18):
//   prefixBudget = maxSteps - 100 = 800, maxSpanTokens = 22, nearBudgetThreshold = 30.
//   AdaptiveConstrainedStepWithPenalties with penaltyTokens = ["{", "}", "**", "^", "\\"].
//   CloseSpanWithinBudget on EOS-in-span or near-budget with full remaining budget.
//
// EXPECTED IMPROVEMENT:
//   11 unterminated → ≤ 3 (threshold + force-open): syntax ~90%+
//   9 tiny wrong → fixed by length-gate: +4-8pp accuracy
//   Net target: accuracy ~55%+, syntax ~90%+
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Branch A (force-open, steps >= prefixBudget):
//   OpenConstrainedSpan sets insideConstrainedOut=true, currentConstrainedOut=[].
//   parser.IsValidPrefix([]) holds by precondition `parser.IsValidPrefix([])`. Preserved.
//
// Branch B (UnconstrainedStep, non-EOS, steps >= threshold, RenderedEndsWith=true):
//   generated already has [next] appended. EnterObservedConstrainedSpan sets
//   insideConstrainedOut=true, currentConstrainedOut=[]. parser.IsValidPrefix([]) by precondition. Preserved.
//
// Branch C (UnconstrainedStep, EOS or steps < threshold or no "<<"):
//   insideConstrainedOut unchanged. If it was false, implication vacuously true.
//   If it was true, currentConstrainedOut unchanged (valid by induction). Preserved.
//
// Branch D (CloseSpanWithinBudget, near-budget or maxSpanTokens):
//   Postcondition: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). Preserved.
//
// Branch E (CloseSpanIfComplete closed=true):
//   insideConstrainedOut set to false by helper; implication vacuously true. Preserved.
//
// Branch F (CloseSpanIfComplete closed=false, AdaptiveConstrained returns valid next):
//   AdaptiveConstrainedStepWithPenalties returns a hard-masked parser-valid next token.
//   AppendConstrainedToken: currentConstrainedOut += [next].
//   By constrained step contract, parser.IsValidPrefix(currentConstrainedOut + [next]). Preserved.
//
// Branch G (AdaptiveConstrained returns EOS, CloseSpanWithinBudget):
//   Postcondition guarantees validity as in Branch D. Preserved.
//
// Invariant 2: |generated| <= |generatedPrefix| + steps
//
// Branch A (OpenConstrainedSpan): appends exactly 1 "<<", steps += 1. |generated| grows 1. Preserved.
// Branch B (UnconstrainedStep non-EOS + EnterObservedConstrainedSpan):
//   generated += [next] (1 token), steps += 1. EnterObservedConstrainedSpan: 0 cost, no append. Preserved.
// Branch C (UnconstrainedStep EOS or no span entry): steps += 1, generated unchanged or grows 1. Preserved.
// Branch D (CloseSpanWithinBudget budget=remainingBudget):
//   |generated| grows ≤ remainingBudget; steps grows by remainingBudget.
//   New steps = old_steps + remainingBudget = maxSteps. |generated| ≤ |gP| + maxSteps. Preserved.
// Branch E (CloseSpanIfComplete closed=true): helper appends ">>" (≤1 token), steps += 1. Preserved.
// Branch F (CloseSpanIfComplete closed=false + AppendConstrainedToken):
//   CloseSpanIfComplete: steps += 1, no visible append (closed=false).
//   AppendConstrainedToken: 0 cost, generated grows 1. Net: both grow by 1. Preserved.
// Branch G (EOS in span, CloseSpanWithinBudget rem=maxSteps-steps):
//   |generated| grows ≤ rem; steps += rem → steps = maxSteps. Preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. Write variable names WITHOUT curly braces. At the very END of your solution, place the complete final answer in <<int(formula)>> using ALL relevant variable names. Use only +, -, *, /, //, % (no ** or ^). Example: <<int(n1 * c1 + n2 * c2 + c3)>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var prefixBudget: nat := if maxSteps > 200 then maxSteps - 100 else (if maxSteps > 100 then maxSteps - 30 else maxSteps / 2);
var naturalEntryThreshold: nat := if maxSteps > 300 then 150 else maxSteps / 6;
var penaltyTokens: seq<Token> := ["{", "}", "**", "^", "\\"];
var spanTokens: nat := 0;
var maxSpanTokens: nat := 22;
var nearBudgetThreshold: nat := 30;
var minSpanLength: nat := 5;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var remainingBudget := maxSteps - steps;
    if steps >= prefixBudget && remainingBudget > 5 {
      // Force open a constrained span for the final answer
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      spanTokens := 0;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // Only enter constrained mode after naturalEntryThreshold to avoid
        // mid-reasoning "<<" (e.g., in prose "End with <<int(formula)>>")
        // firing on space-prefixed tokens that RenderedEndsWith catches but
        // exact equality misses.
        if steps >= naturalEntryThreshold && RenderedEndsWith(generated, "<<") {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
          spanTokens := 0;
        }
      }
    }
  } else {
    // Inside constrained span
    var remainingBudget := maxSteps - steps;

    // Near budget end or span too long: force close with all remaining budget
    if remainingBudget <= nearBudgetThreshold || spanTokens >= maxSpanTokens {
      if remainingBudget > 0 {
        var sg, si, sc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := sg;
        insideConstrainedOut := si;
        currentConstrainedOut := sc;
        steps := steps + remainingBudget;
      }
      break;
    }

    // Try to close if complete (costs 1 step)
    var preCloseLen := |currentConstrainedOut|;
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      // Only break if the span was substantial (not a tiny partial formula)
      // Tiny spans (< minSpanLength) continue, allowing the model to write
      // the full formula in a subsequent span; evaluator uses the last span.
      if preCloseLen >= minSpanLength {
        break;
      }
      spanTokens := 0;
    } else {
      // Generate next constrained token with penalties on invalid characters
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStepWithPenalties(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 2.0,
        penaltyTokens, 8.0,
        6, eosToken
      );
      if next == eosToken {
        // EOS inside span: use all remaining budget for forced close
        var rem := maxSteps - steps;
        if rem > 0 {
          var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem
          );
          generated := sg2;
          insideConstrainedOut := si2;
          currentConstrainedOut := sc2;
          steps := steps + rem;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        spanTokens := spanTokens + 1;
      }
    }
  }
}

